parameters.jsCode:
const item = $input.first();

// Step 1: Extract raw text from OpenAI response
let rawText = '';
try {
  rawText = item.json.choices[0].message.content;
} catch (e) {
  rawText = '';
}

// Step 2: Strip markdown fences and parse JSON
let parsed;
try {
  const cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

// Step 3: Allowed value sets
const validUrgency = ['routine', 'urgent', 'emergency'];
const validClassification = ['consultation', 'follow_up', 'demo', 'support', 'onboarding', 'general'];
const validChannel = ['video', 'phone', 'in_person'];

// Step 4: Validate and apply safe defaults for every field
const result = {
  urgency: validUrgency.includes(parsed.urgency)
    ? parsed.urgency
    : 'routine',

  validated_date: (typeof parsed.validated_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(parsed.validated_date))
    ? parsed.validated_date
    : null,

  validated_time: (typeof parsed.validated_time === 'string' && /^\d{2}:\d{2}$/.test(parsed.validated_time))
    ? parsed.validated_time
    : null,

  is_business_hours: typeof parsed.is_business_hours === 'boolean'
    ? parsed.is_business_hours
    : true,

  suggested_slot: (typeof parsed.suggested_slot === 'string' && parsed.suggested_slot.length > 0)
    ? parsed.suggested_slot
    : 'Next available weekday at 10:00',

  appointment_duration_minutes: (Number.isInteger(parsed.appointment_duration_minutes) && parsed.appointment_duration_minutes > 0)
    ? parsed.appointment_duration_minutes
    : 30,

  classification: validClassification.includes(parsed.classification)
    ? parsed.classification
    : 'general',

  channel_recommendation: validChannel.includes(parsed.channel_recommendation)
    ? parsed.channel_recommendation
    : 'video',

  preparation_notes: (typeof parsed.preparation_notes === 'string' && parsed.preparation_notes.length > 0)
    ? parsed.preparation_notes
    : 'Review client history before the meeting.',

  client_confirmation_message: (typeof parsed.client_confirmation_message === 'string' && parsed.client_confirmation_message.length > 0)
    ? parsed.client_confirmation_message
    : 'Thank you for your request. We will confirm your appointment shortly.'
};

return [{ json: result }];
